/** Coordinate ownership, independent of any plugin's update transport or rendering. */
export const createScrollBindings = () => {
    let acknowledged = [];
    let viewportWidth = 0;
    const motion = new WeakMap();
    const reuse = (candidate, width) => {
        const next = candidate.control.scroll;
        if (!candidate.scrollElement || !next || viewportWidth !== width)
            return false;
        return acknowledged.some((previous) => {
            const current = previous.control.scroll;
            return (previous.scrollElement === candidate.scrollElement &&
                current?.id === next.id &&
                current.contentWidth === next.contentWidth &&
                current.contentHeight === next.contentHeight &&
                ['viewport', 'clip'].every((key) => ['x', 'y', 'width', 'height'].every((axis) => current[key][axis] === next[key][axis])));
        });
    };
    return {
        reuse,
        acknowledge(sources, width) {
            acknowledged = sources;
            viewportWidth = width;
        },
        changed(owner) {
            motion.set(owner, { version: (motion.get(owner)?.version ?? 0) + 1, moving: true });
        },
        settled(owner) {
            const state = motion.get(owner);
            if (state)
                state.moving = false;
        },
        eligible(candidate, width) {
            return !candidate.scrollElement || !motion.get(candidate.scrollElement)?.moving || reuse(candidate, width);
        },
        acquiring(sources, width) {
            return new Map(sources.flatMap((source) => source.scrollElement && !reuse(source, width)
                ? [[source.scrollElement, motion.get(source.scrollElement)?.version ?? 0]]
                : []));
        },
        unconfirmed(sources, acquiring) {
            return new Set(sources.flatMap((source) => {
                const owner = source.scrollElement, sample = source.control.scroll;
                return owner &&
                    sample &&
                    acquiring.has(owner) &&
                    (acquiring.get(owner) !== (motion.get(owner)?.version ?? 0) ||
                        owner.scrollLeft !== sample.offsetX ||
                        owner.scrollTop !== sample.offsetY)
                    ? [owner]
                    : [];
            }));
        },
    };
};
